class LicenseStateEnum(OpenStrEnum):
    """
    All states a license can be in
    """

    OK = "ok"
    RELEASED = "released"
    TERMINATED = "terminated"
    TO_DELIVER = "toDeliver"


class LicenseTaskStateEnum(OpenStrEnum):
    """
    All states a license Task can be in
    """

    CANCELLED = "cancelled"
    DOING = "doing"
    DONE = "done"
    ERROR = "error"
    TODO = "todo"


class ServiceRenewalTypeEnum(OpenStrEnum):
    """
    Detailed renewal type of a service
    """

    AUTOMATIC_FORCED_PRODUCT = "automaticForcedProduct"
    AUTOMATIC_V2012 = "automaticV2012"
    AUTOMATIC_V2014 = "automaticV2014"
    AUTOMATIC_V2016 = "automaticV2016"
    AUTOMATIC_V2024 = "automaticV2024"
    MANUAL = "manual"
    ONE_SHOT = "oneShot"
    OPTION = "option"


class ServiceStateEnum(OpenStrEnum):
    AUTORENEW_IN_PROGRESS = "autorenewInProgress"
    EXPIRED = "expired"
    IN_CREATION = "inCreation"
    OK = "ok"
    PENDING_DEBT = "pendingDebt"
    UN_PAID = "unPaid"


class ServiceTerminationFutureUseEnum(OpenStrEnum):
    """
    All future uses you can provide for a service termination
    """

    NOT_REPLACING_SERVICE = "NOT_REPLACING_SERVICE"
    OTHER = "OTHER"
    SUBSCRIBE_AN_OTHER_SERVICE = "SUBSCRIBE_AN_OTHER_SERVICE"
    SUBSCRIBE_OTHER_KIND_OF_SERVICE_WITH_COMPETITOR = (
        "SUBSCRIBE_OTHER_KIND_OF_SERVICE_WITH_COMPETITOR"
    )
    SUBSCRIBE_SIMILAR_SERVICE_WITH_COMPETITOR = (
        "SUBSCRIBE_SIMILAR_SERVICE_WITH_COMPETITOR"
    )


class ServiceTerminationReasonEnum(OpenStrEnum):
    """
    All reasons you can provide for a service termination
    """

    FEATURES_DONT_SUIT_ME = "FEATURES_DONT_SUIT_ME"
    LACK_OF_PERFORMANCES = "LACK_OF_PERFORMANCES"
    MIGRATED_TO_ANOTHER_OVH_PRODUCT = "MIGRATED_TO_ANOTHER_OVH_PRODUCT"
    MIGRATED_TO_COMPETITOR = "MIGRATED_TO_COMPETITOR"
    NOT_ENOUGH_RECOGNITION = "NOT_ENOUGH_RECOGNITION"
    NOT_NEEDED_ANYMORE = "NOT_NEEDED_ANYMORE"
    NOT_RELIABLE = "NOT_RELIABLE"
    NO_ANSWER = "NO_ANSWER"
    OTHER = "OTHER"
    PRODUCT_DIMENSION_DONT_SUIT_ME = "PRODUCT_DIMENSION_DONT_SUIT_ME"
    PRODUCT_TOOLS_DONT_SUIT_ME = "PRODUCT_TOOLS_DONT_SUIT_ME"
    TOO_EXPENSIVE = "TOO_EXPENSIVE"
    TOO_HARD_TO_USE = "TOO_HARD_TO_USE"
    UNSATIFIED_BY_CUSTOMER_SUPPORT = "UNSATIFIED_BY_CUSTOMER_SUPPORT"


class IamResourceMetadata(OVHModel):
    """
    IAM resource metadata embedded in services models
    """

    display_name: str | None = Field(default=None, alias="displayName")
    """
    Resource display name
    """
    id: str
    """
    Unique identifier of the resource
    """
    state: IamResourceMetadataStateEnum | None = None
    """
    Resource state
    """
    tags: dict[str, str] | None = None
    """
    Resource tags. Tags that were internally computed are prefixed with ovh:
    """
    urn: str
    """
    Unique resource name used in policies
    """


class IamResourceTagFilter(OVHModel):
    """
    Resource tag filter
    """

    operator: IamResourceTagFilterOperatorEnum | None = None
    """
    Operator to use in order to filter on the value (defaults to 'EQ')
    """
    value: str
    """
    Value to use in order to filter tags
    """


class LicenseOrderableSqlServerCompatibilityInfos(OVHModel):
    """
    All options available for SQL Server products
    """

    version: LicenseSqlServerVersionEnum


class LicenseSqlServerOrderConfiguration(OVHModel):
    """
    Allowed SQL Server versions and their compliant options per matching serviceTypes
    """

    orderable_versions: list[LicenseOrderableSqlServerCompatibilityInfos] = Field(
        alias="orderableVersions"
    )
    service_type: LicenseLicenseTypeEnum = Field(alias="serviceType")


class LicenseTask(OVHModel):
    """
    licenses Todos
    """

    action: LicenseActionType
    """
    This Task description
    """
